export function SearchScope({
  label = "{{label}}",
  scope = "{{scope}}",
  accent = "{{accent}}",
  radius = {{radius}},
}) {
  const hint = {
    everywhere: "Everywhere — results span the whole workspace.",
    project: "This project — results are limited to the current project.",
    mine: "My items — results are limited to things you own.",
  }[scope] ?? scope;
  return (
    <div style={{ display: "block", fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 260 }}>
      <label htmlFor="sscope-select" style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>{label}</label>
      <select id="sscope-select" defaultValue={scope} style={{
        width: "100%", boxSizing: "border-box", padding: "9px 11px", font: "inherit", color: "#241430",
        background: "#FAF7F2", border: "1.5px solid #24143026", borderRadius: radius, appearance: "none",
      }}>
        <option value="everywhere">Everywhere</option>
        <option value="project">This project</option>
        <option value="mine">My items</option>
      </select>
      <p style={{ margin: "6px 0 0", fontSize: 12, color: "#24143090" }}>{hint}</p>
    </div>
  );
}
